<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>MEETA — Handmade Stories, Crafted With Love</title>
<meta name="description" content="Discover authentic Indian handicrafts and support local artisans on MEETA.">
<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600&family=Playfair+Display:wght@500;600&display=swap" rel="stylesheet">
<style>
:root{--ink:#211b18;--brown:#944700;--soft:#fff2e9;--paper:#fffaf6;--line:#ead7cc;--muted:#6e6059}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;color:var(--ink);font-family:"DM Sans",sans-serif;background:var(--paper)}a{text-decoration:none;color:inherit}button,input{font:inherit}.wrap{max-width:1260px;margin:auto;padding-left:28px;padding-right:28px}
header{height:84px;background:rgba(255,250,246,.95);border-bottom:1px solid var(--line);position:sticky;top:0;z-index:20}.nav{height:100%;display:flex;align-items:center;gap:30px}.logo{display:flex;align-items:center;gap:12px;margin-right:auto}.mark{height:48px;width:27px;border-left:2px solid;border-right:2px solid;position:relative}.mark:before,.mark:after{content:"";position:absolute;left:-6px;right:-6px;border-top:2px solid}.mark:before{top:8px}.mark:after{top:16px}.brand{font-size:20px;letter-spacing:.35em}.brand small{font-size:6px;display:block;color:#85766e;letter-spacing:.4em;margin-top:5px}.links{display:flex;gap:28px;font-size:14px}.links a{padding:32px 0}.links .active{color:var(--brown);border-bottom:2px solid}.search{display:flex;width:225px;padding:11px 15px;border:1px solid var(--line);border-radius:12px}.search input{border:0;outline:0;background:transparent;width:100%;margin-left:8px}.actions{display:flex;align-items:center;gap:16px}.icon{font-size:22px;line-height:1}.account{font-size:13px}.menu{display:none;border:0;background:none;font-size:24px}
.hero{background:linear-gradient(115deg,#fff3eb,#ffe3d4);min-height:690px;overflow:hidden}.hero-grid{min-height:690px;display:grid;grid-template-columns:1fr 1fr;align-items:center}.copy{padding:55px 0}.pill{display:inline-flex;gap:8px;align-items:center;border-radius:30px;background:#f3dfd3;padding:8px 15px;color:var(--brown);font-size:11px;letter-spacing:.13em;text-transform:uppercase}.copy h1{font-size:70px;line-height:1.04;letter-spacing:-.04em;font-weight:500;margin:34px 0}.copy h1 span{color:var(--brown)}.copy p{font-size:18px;line-height:1.7;color:#5d4f48;max-width:560px}.buttons{display:flex;gap:14px;margin-top:38px}.btn{border:1px solid #c7aa98;padding:16px 28px;border-radius:10px;font-weight:600;cursor:pointer;background:rgba(255,255,255,.45)}.btn.primary{background:var(--brown);color:#fff;border-color:var(--brown)}.visual{height:100%;position:relative;display:grid;place-items:center}.visual:before{content:"";position:absolute;width:560px;height:560px;border:2px dashed rgba(148,71,0,.1);border-radius:50%}.visual img{position:relative;width:78%;height:570px;object-fit:cover;border-radius:46% 46% 12px 12px;filter:saturate(.8) sepia(.08);box-shadow:0 30px 55px rgba(77,39,15,.18)}.stat{position:absolute;background:#fff;padding:17px 22px;border-radius:12px;box-shadow:0 12px 30px #7b3f1f21}.stat strong{display:block}.stat.one{right:0;top:140px}.stat.two{left:0;bottom:130px}
.section{padding:85px 0}.section.alt{background:#fff}.heading{text-align:center;margin-bottom:46px}.heading small{color:var(--brown);letter-spacing:.22em;text-transform:uppercase}.heading h2{font-family:"Playfair Display";font-size:40px;margin:12px 0}.heading p{color:var(--muted)}.categories{display:grid;grid-template-columns:repeat(4,1fr);gap:22px}.cat{height:330px;position:relative;border-radius:150px 150px 12px 12px;overflow:hidden;background:#eadfd7}.cat img{width:100%;height:100%;object-fit:cover;transition:.5s}.cat:hover img{transform:scale(1.05)}.cat:after{content:"";position:absolute;inset:45% 0 0;background:linear-gradient(transparent,#1b0c03d6)}.cat h3{position:absolute;z-index:2;bottom:22px;left:0;right:0;text-align:center;color:#fff;font-family:"Playfair Display";font-size:25px}.products{display:grid;grid-template-columns:repeat(4,1fr);gap:22px}.product{border:1px solid var(--line);border-radius:12px;padding:9px;background:#fff}.product .pic{height:245px;overflow:hidden;border-radius:8px;background:#eee}.product img{width:100%;height:100%;object-fit:cover}.product h3{font-size:16px;margin:16px 4px 7px}.meta{display:flex;justify-content:space-between;color:var(--brown);margin:0 4px 13px}.add{width:100%;padding:12px;border:0;border-radius:7px;background:#f2e8e1;color:var(--brown);font-weight:600;cursor:pointer}.add:hover{background:var(--brown);color:#fff}
.vendor{margin:60px auto 90px;background:linear-gradient(120deg,#3b2a22,#7d3e1d);color:white;border-radius:28px;padding:65px;display:flex;align-items:center;justify-content:space-between;gap:30px}.vendor h2{font-family:"Playfair Display";font-size:42px;margin:0 0 12px}.vendor p{opacity:.8;max-width:650px;line-height:1.6}.vendor .btn{background:#fff;color:var(--brown);white-space:nowrap}.notice{position:fixed;right:24px;bottom:24px;background:#241a15;color:#fff;padding:14px 20px;border-radius:10px;display:none;z-index:50}.nav-menu{position:relative}.nav-menu>summary{list-style:none;cursor:pointer;display:flex;align-items:center;gap:7px}.nav-menu>summary::-webkit-details-marker{display:none}.avatar{width:31px;height:31px;border-radius:50%;display:grid;place-items:center;background:#f1e3da;color:var(--brown);font-weight:600;overflow:hidden}.avatar img{width:100%;height:100%;object-fit:cover}.dropdown{position:absolute;right:0;top:42px;width:245px;background:#fff;border:1px solid var(--line);border-radius:12px;box-shadow:0 18px 50px #43210f24;padding:10px;z-index:40}.dropdown .who{padding:11px 12px;border-bottom:1px solid var(--line);margin-bottom:5px}.dropdown .who small{display:block;color:var(--muted);margin-top:3px}.dropdown a,.dropdown button{display:flex;width:100%;border:0;background:none;padding:11px 12px;border-radius:7px;color:var(--ink);cursor:pointer;text-align:left}.dropdown a:hover,.dropdown button:hover{background:#fff3eb;color:var(--brown)}footer{background:#2e2723;color:#eee}.footer{padding:50px 28px;display:grid;grid-template-columns:1.4fr repeat(3,1fr);gap:45px}.footer h4{margin-top:0}.footer p,.footer a{display:block;color:#c9bdb6;line-height:2;font-size:13px}.admin-link{opacity:.5}
@media(max-width:1000px){.links{display:none}.menu{display:block}.hero-grid{grid-template-columns:1fr}.hero{min-height:auto}.copy{text-align:center}.copy p{margin:auto}.buttons{justify-content:center}.visual{height:560px}.products,.categories{grid-template-columns:repeat(2,1fr)}.footer{grid-template-columns:repeat(2,1fr)}}@media(max-width:650px){header{height:70px}.nav{padding:0 18px}.search,.actions .icon:first-child,.account{display:none}.brand{font-size:16px}.mark{height:40px}.wrap{padding-left:18px;padding-right:18px}.hero-grid{padding-top:22px}.copy h1{font-size:48px}.copy p{font-size:16px}.buttons{flex-direction:column}.visual{height:440px}.visual img{height:400px;width:90%}.stat{font-size:12px}.stat.one{right:4px;top:40px}.stat.two{left:4px;bottom:45px}.section{padding:60px 0}.categories,.products{grid-template-columns:1fr}.cat{height:400px}.vendor{margin:30px 18px 60px;padding:40px 25px;display:block}.vendor h2{font-size:34px}.vendor .btn{display:inline-block;margin-top:18px}.footer{grid-template-columns:1fr}}
</style><style>
.section-head{display:flex;align-items:end;justify-content:space-between;margin-bottom:30px}.section-head h2{font-size:34px;margin:0 0 5px}.section-head p{margin:0;color:var(--muted)}.rail{display:grid;grid-auto-flow:column;grid-auto-columns:minmax(270px,1fr);gap:22px;overflow-x:auto;padding-bottom:12px}.region{border:1px solid var(--line);padding:9px;border-radius:12px;background:#fff}.region img{height:210px;width:100%;object-fit:cover;border-radius:8px}.region h3{font-size:22px;color:var(--brown);margin:14px 3px 6px}.region p{font-size:14px;color:var(--muted);min-height:42px;margin:0 3px 14px}.region a{font-size:11px;text-transform:uppercase;color:var(--brown);letter-spacing:.1em}.sale{margin:0 auto 80px;background:linear-gradient(110deg,#67300d,#9b520f);color:#fff;border-radius:28px;text-align:center;padding:60px 25px}.sale h2{font-size:52px;font-weight:500;margin:20px}.sale small{letter-spacing:.28em;text-transform:uppercase}.sale .btn{display:inline-block;background:#fff;color:var(--brown);margin-top:18px}.new-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:22px}.new-card img{width:100%;height:310px;object-fit:cover;border-radius:18px}.new-card h3{margin:12px 0 4px}.new-card span{color:var(--brown)}.testimonials{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}.quote{border:1px solid var(--line);border-radius:16px;padding:28px;background:#fff}.stars{color:var(--brown)}.quote blockquote{margin:17px 0;line-height:1.65;font-style:italic;color:#50433d}.quote small{color:var(--brown)}.occasions{background:#312b27;color:white;padding:80px 0}.occasion-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:24px}.occasion{height:340px;border-radius:22px;overflow:hidden;position:relative}.occasion img{width:100%;height:100%;object-fit:cover}.occasion:after{content:"";position:absolute;inset:30% 0 0;background:linear-gradient(transparent,#000c)}.caption{position:absolute;z-index:2;left:30px;bottom:28px}.caption h3{font-size:27px;margin:0 0 8px}.articles{display:grid;grid-template-columns:repeat(3,1fr);gap:28px}.article img{width:100%;height:210px;object-fit:cover;border-radius:12px}.article small{display:block;color:var(--brown);letter-spacing:.14em;text-transform:uppercase;margin-top:15px}.article h3{font-size:20px;margin:9px 0}.article p{color:var(--muted)}.newsletter-form{display:flex;border:1px solid #ffffff42;border-radius:8px;overflow:hidden}.newsletter-form input{width:100%;min-width:0;background:transparent;border:0;color:#fff;padding:10px}.newsletter-form button{border:0;background:#fff;color:var(--brown);padding:0 15px}@media(max-width:900px){.new-grid{grid-template-columns:repeat(2,1fr)}.testimonials,.articles{grid-template-columns:1fr 1fr}}@media(max-width:650px){.new-grid,.testimonials,.articles,.occasion-grid{grid-template-columns:1fr}.sale h2{font-size:36px}.section-head{display:block}}
.mobile-drawer{display:none;position:fixed;inset:70px 0 0;background:#fffaf6;z-index:60;padding:20px;overflow:auto}.mobile-drawer.open{display:block}.mobile-drawer a,.mobile-drawer button{display:flex;width:100%;padding:15px 8px;border:0;border-bottom:1px solid var(--line);background:none;text-align:left;color:var(--ink)}.mobile-drawer h4{margin:24px 8px 6px;color:var(--brown);font-size:12px;letter-spacing:.14em;text-transform:uppercase}.mobile-search{display:flex;border:1px solid var(--line);border-radius:10px;padding:12px;margin-bottom:12px}.mobile-search input{width:100%;border:0;outline:0;background:none}.menu[aria-expanded="true"]{color:var(--brown)}@media(min-width:1001px){.mobile-drawer{display:none!important}}
</style></head><body>
<header><nav class="nav wrap"><a class="logo" href="/"><span class="mark"></span><span class="brand">MEETA<small>HOME DECOR HUB</small></span></a><div class="links"><a class="active" href="/">Home</a><a href="/categories">Categories</a><a href="#">By State</a><a href="#">Artisans</a><a href="#">Collections</a><a href="#">Offers</a></div><label class="search">⌕<input id="search" placeholder="Search crafts..."></label><div class="actions"><a class="icon protected-link" href="/wishlist" aria-label="Wishlist">♡</a><a class="protected-link" href="/cart" aria-label="Shopping cart" style="display:flex;align-items:center;gap:5px"><span style="font-size:22px">🛒</span><span class="account">Cart</span><sup id="homeCartCount" style="display:none;background:#944700;color:white;border-radius:12px;padding:2px 6px">0</sup></a><div id="customerNav"><a class="account" href="/login?redirect=/">Sign in</a></div><details class="nav-menu"><summary class="account">More⌄</summary><div class="dropdown"><a href="/vendor/register">Become an Artisan</a><a href="/vendor/login">Vendor sign in</a><a href="/admin/login">Admin portal</a><a href="#">Help & support</a></div></details></div><button class="menu">☰</button></nav></header>
<main><section class="hero"><div class="hero-grid wrap"><div class="copy"><span class="pill">✦ Artisan marketplace</span><h1>Handmade Stories.<br><span>Crafted With Love.</span></h1><p>Discover India's finest handmade crafts from local artisans. Every piece tells a story of heritage, skill, and soul.</p><div class="buttons"><a class="btn primary" href="/categories">Shop Collection</a><a class="btn" href="/vendor/register">Join as Artisan</a></div></div><div class="visual"><img src="https://images.unsplash.com/photo-1610701596007-11502861dcfa?auto=format&fit=crop&w=1000&q=90" alt="Handmade terracotta pottery"><div class="stat one"><strong>50,000+</strong><small>MASTERPIECES</small></div><div class="stat two"><strong>5,000+</strong><small>HERITAGE SELLERS</small></div></div></div></section>
<section class="section"><div class="wrap"><div class="heading"><small>Made across India</small><h2>Browse By Category</h2><p>Find a craft that speaks to your space and your story.</p></div><div id="categories" class="categories"></div></div></section>
<section class="section alt"><div class="wrap"><div class="section-head"><div><h2>Heritage Across India</h2><p>Discover unique crafts born from India's diverse cultural roots.</p></div></div><div id="regions" class="rail"></div></div></section>
<section class="section"><div class="wrap"><div class="heading"><small>Community favourites</small><h2>Best Selling Products</h2></div><div id="bestSelling" class="products"></div></div></section>
<div class="sale wrap"><small>Limited time heritage sale</small><h2>FESTIVAL SPECIAL<br>UP TO 50% OFF</h2><p>Celebrate Indian heritage with our hand-picked curated collections.</p><a class="btn" href="#trending">Explore Sale Now</a></div>
<section class="section alt" id="trending"><div class="wrap"><div class="section-head"><div><h2>Trending Masterpieces</h2><p>Currently the most-loved pieces in our artisan community.</p></div></div><div id="products" class="products"></div></div></section>
<section class="section"><div class="wrap"><div class="section-head"><div><h2>New Arrivals</h2><p>The latest unique pieces added to our artisan marketplace.</p></div></div><div id="newArrivals" class="new-grid"></div></div></section>
<section class="section alt"><div class="wrap"><div class="heading"><h2>What Our Community Says</h2></div><div id="testimonials" class="testimonials"></div></div></section>
<section class="occasions"><div class="wrap"><div class="heading"><h2>Curated For Every Occasion</h2><p>Hand-picked selections that bring character and heritage to your home.</p></div><div id="occasions" class="occasion-grid"></div></div></section>
<section class="section"><div class="wrap"><div class="heading"><h2>Latest Stories & Insights</h2></div><div id="articles" class="articles"></div></div></section>
<section class="vendor wrap"><div><h2>Start Selling Your Artisan Creations</h2><p>Join a growing community of Indian makers. Build your digital storefront and take your craftsmanship to customers everywhere.</p></div><a href="/vendor/register" class="btn">Join as Artisan →</a></section></main>
<footer><div class="footer wrap"><div><div class="brand">MEETA<small>HOME DECOR HUB</small></div><p>Connecting the world with authentic Indian craftsmanship while empowering local artisans.</p></div><div><h4>Marketplace</h4><a href="/categories">Categories</a><a href="#">By State</a><a href="#">Offers</a></div><div><h4>For artisans</h4><a href="/vendor/register">Join as Artisan</a><a href="/vendor/login">Vendor Sign In</a><a href="#">Seller Help</a></div><div><h4>Join the circle</h4><p>Early access to new collections and artisan stories.</p><form id="newsletter" class="newsletter-form"><input type="email" required placeholder="Your email"><button>→</button></form><a class="admin-link" href="/admin/login">Admin portal</a></div></div></footer><div id="notice" class="notice">Please sign in to add items to your cart.</div>
<script>
const fallbackCats=[['Pottery','https://images.unsplash.com/photo-1610701596007-11502861dcfa?auto=format&fit=crop&w=700&q=85'],['Woodwork','https://images.unsplash.com/photo-1452860606245-08befc0ff44b?auto=format&fit=crop&w=700&q=85'],['Textiles','https://images.unsplash.com/photo-1606293926075-69a00dbfde81?auto=format&fit=crop&w=700&q=85'],['Home Decor','https://images.unsplash.com/photo-1618220179428-22790b461013?auto=format&fit=crop&w=700&q=85']];
const demoProducts=[{name:'Classic Blue Pottery Plate',image:'https://images.unsplash.com/photo-1610701596007-11502861dcfa?auto=format&fit=crop&w=700&q=85',effective_price:1499,rating:4.9},{name:'Carved Walnut Bowl',image:'https://images.unsplash.com/photo-1578749556568-bc2c40e68b61?auto=format&fit=crop&w=700&q=85',effective_price:2100,rating:4.8},{name:'Embroidered Silk Shawl',image:'https://images.unsplash.com/photo-1606293926075-69a00dbfde81?auto=format&fit=crop&w=700&q=85',effective_price:3450,rating:5},{name:'Dhokra Metal Piece',image:'https://images.unsplash.com/photo-1577702312706-e23ff063064f?auto=format&fit=crop&w=700&q=85',effective_price:4999,rating:4.7}];
const fillProducts=items=>[...(items||[]),...demoProducts].filter((x,i,a)=>a.findIndex(y=>y.name===x.name)===i).slice(0,4);
const money=n=>'₹'+Number(n||0).toLocaleString('en-IN');
fetch('/api/home?per_page=8').then(r=>r.json()).then(({data})=>{const live=(data.categories||[]).map((c,i)=>[c.name,c.image||fallbackCats[i%4][1],c.id]),names=new Set(live.map(c=>c[0].toLowerCase())),cs=[...live,...fallbackCats.filter(c=>!names.has(c[0].toLowerCase()))].slice(0,4);document.getElementById('categories').innerHTML=cs.map(c=>`<a class="cat" href="/shop${c[2]?'?category_id='+c[2]:''}"><img src="${c[1]}" alt="${c[0]}"><h3>${c[0]}</h3></a>`).join('')}).catch(()=>{document.getElementById('categories').innerHTML=fallbackCats.map(c=>`<a class="cat" href="/categories"><img src="${c[1]}" alt="${c[0]}"><h3>${c[0]}</h3></a>`).join('')});
const productCards=items=>fillProducts(items).map(p=>`<article class="product">${p.slug?`<a href="/products/${p.slug}">`:''}<div class="pic"><img src="${p.image}" alt="${p.name}"></div><h3>${p.name}</h3>${p.slug?'</a>':''}<div class="meta"><span>${money(p.effective_price)}</span><span>★ ${p.rating||'New'}</span></div></article>`).join('');
fetch('/api/home?per_page=8').then(r=>r.json()).then(({data})=>{
 document.getElementById('regions').innerHTML=(data.regions||[]).map(x=>`<article class="region"><img src="${x.image_url}" alt="${x.name}"><h3>${x.name}</h3><p>${x.description||''}</p><a href="#">View collection →</a></article>`).join('');
 document.getElementById('bestSelling').innerHTML=productCards(data.best_selling);
 document.getElementById('products').innerHTML=productCards(data.trending);
 document.getElementById('newArrivals').innerHTML=fillProducts(data.new_arrivals).map(p=>`<article class="new-card"><img src="${p.image}" alt="${p.name}"><h3>${p.name}</h3><span>${money(p.effective_price)}</span></article>`).join('');
 document.getElementById('testimonials').innerHTML=(data.testimonials||[]).map(x=>`<article class="quote"><div class="stars">★★★★★</div><blockquote>“${x.quote}”</blockquote><strong>${x.customer_name}</strong><small>${x.customer_title||''}</small></article>`).join('');
 document.getElementById('occasions').innerHTML=(data.collections||[]).map(x=>`<article class="occasion"><img src="${x.image_url}" alt="${x.name}"><div class="caption"><h3>${x.name}</h3><p>${x.description||''}</p></div></article>`).join('');
 document.getElementById('articles').innerHTML=(data.articles||[]).map(x=>`<article class="article"><img src="${x.image_url}" alt="${x.title}"><small>${x.category||'Stories'}</small><h3>${x.title}</h3><p>${x.excerpt||''}</p></article>`).join('');
});
document.getElementById('newsletter').addEventListener('submit',async e=>{e.preventDefault();const input=e.target.querySelector('input'),res=await fetch('/api/newsletter/subscribe',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({email:input.value})});const data=await res.json();document.getElementById('notice').textContent=data.message||'Thank you';document.getElementById('notice').style.display='block';if(res.ok)input.value='';setTimeout(()=>document.getElementById('notice').style.display='none',2500)});
async function syncCustomerHeader(){const savedToken=localStorage.getItem('meeta_token'),nav=document.getElementById('customerNav');if(!savedToken){nav.innerHTML='<a class="account" href="/login?redirect=/">Sign in</a>';return}try{const response=await fetch('/api/customer/account/profile',{headers:{Accept:'application/json',Authorization:'Bearer '+savedToken}});if(!response.ok)throw Error('invalid session');const {data:user}=await response.json(),name=user.display_name||user.first_name||'Account',initial=name.charAt(0).toUpperCase(),avatar=user.profile_image_url?`<img src="${user.profile_image_url}" alt="${name}">`:initial;nav.innerHTML=`<details class="nav-menu"><summary><span class="avatar">${avatar}</span><span class="account">${name}</span><span>⌄</span></summary><div class="dropdown"><div class="who"><strong>${user.full_name||name}</strong><small>${user.email}</small></div><a href="/account">My account</a><a href="/orders">My orders</a><a href="/wishlist">Wishlist</a><a href="/account/settings">Settings</a><button id="customerLogout" type="button">Sign out</button></div></details>`;document.getElementById('customerLogout').onclick=async()=>{try{await fetch('/api/logout',{method:'POST',headers:{Accept:'application/json',Authorization:'Bearer '+savedToken}})}finally{localStorage.removeItem('meeta_token');localStorage.removeItem('meeta_user');location.href='/'}};const cartResponse=await fetch('/api/customer/cart',{headers:{Accept:'application/json',Authorization:'Bearer '+savedToken}});if(cartResponse.ok){const cart=(await cartResponse.json()).data,badge=document.getElementById('homeCartCount');badge.textContent=cart.items_count||0;badge.style.display=cart.items_count?'inline':'none'}}catch(error){localStorage.removeItem('meeta_token');localStorage.removeItem('meeta_user');nav.innerHTML='<a class="account" href="/login?redirect=/">Sign in</a>'}}
syncCustomerHeader();
document.querySelectorAll('.protected-link').forEach(link=>link.onclick=e=>{if(!localStorage.getItem('meeta_token')){e.preventDefault();location.href='/login?redirect='+encodeURIComponent(link.getAttribute('href'))}});
function closeDropdowns(except=null){document.querySelectorAll('details.nav-menu[open]').forEach(menu=>{if(menu!==except)menu.removeAttribute('open')})}
document.addEventListener('click',event=>{const active=event.target.closest('details.nav-menu');if(!active)closeDropdowns();else closeDropdowns(active);if(event.target.closest('.dropdown a'))active?.removeAttribute('open')});document.addEventListener('keydown',event=>{if(event.key==='Escape'){closeDropdowns();closeMobileNav()}});
const mobileDrawer=document.createElement('aside');mobileDrawer.id='mobileDrawer';mobileDrawer.className='mobile-drawer';mobileDrawer.setAttribute('aria-label','Mobile navigation');document.querySelector('header').after(mobileDrawer);const menuButton=document.querySelector('.menu');menuButton.setAttribute('aria-label','Open navigation');menuButton.setAttribute('aria-controls','mobileDrawer');menuButton.setAttribute('aria-expanded','false');
function renderMobileNav(){const loggedIn=Boolean(localStorage.getItem('meeta_token'));mobileDrawer.innerHTML=`<label class="mobile-search">⌕<input id="mobileSearch" placeholder="Search crafts..."></label><h4>Explore</h4><a href="/">Home</a><a href="/categories">Categories</a><a href="/shop">All products</a><a href="#">By State</a><a href="#">Artisans</a><a href="#">Collections</a><a href="#">Offers</a><h4>${loggedIn?'Your account':'Account'}</h4>${loggedIn?'<a href="/account">My account</a><a href="/orders">My orders</a><a href="/wishlist">Wishlist</a><a href="/cart">Cart</a><a href="/account/settings">Settings</a><button id="mobileLogout" type="button">Sign out</button>':'<a href="/login?redirect=/">Sign in</a><a href="/register?redirect=/">Create account</a>'}<h4>For partners</h4><a href="/vendor/register">Become an Artisan</a><a href="/vendor/login">Vendor sign in</a><a href="/admin/login">Admin portal</a><a href="#">Help & support</a>`;document.getElementById('mobileSearch').onkeydown=event=>{if(event.key==='Enter'&&event.target.value.trim())location.href='/shop?search='+encodeURIComponent(event.target.value.trim())};document.getElementById('mobileLogout')?.addEventListener('click',()=>document.getElementById('customerLogout')?.click());mobileDrawer.querySelectorAll('a').forEach(link=>link.onclick=closeMobileNav)}
function closeMobileNav(){mobileDrawer.classList.remove('open');menuButton.setAttribute('aria-expanded','false');document.body.style.overflow=''}menuButton.onclick=()=>{const opening=!mobileDrawer.classList.contains('open');renderMobileNav();mobileDrawer.classList.toggle('open',opening);menuButton.setAttribute('aria-expanded',String(opening));document.body.style.overflow=opening?'hidden':''};setTimeout(renderMobileNav,400);
document.getElementById('search').addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.value.trim())location.href='/shop?search='+encodeURIComponent(e.target.value.trim())});
</script></body></html>
